    last_synced_at, created_at, updated_at
) VALUES (
    (SELECT id FROM attendance_devices WHERE serial_number = 'BYRQ211860043'),
    '23061',
    (SELECT id FROM employees WHERE employee_code = '23061'),
    'YOUEN KIMHEANG.YOUEN KIM',
    'NORMAL_USER',
    NULL,
    NULL,
    FALSE,
    0,
